with valid as (select *, case when country in ('DE', 'TH') then 'Priority' else 'Other' end as country_group from customers where credit_limit between 8900 and 12300), with_latest as (select s.id, s.country, s.city, s.segment, s.is_active, latest.session_country, latest.session_device from valid s left join lateral (select c.country as session_country, c.device as session_device from sessions c where c.customer_id = s.id order by c.started_at desc, c.id desc limit 1) latest on true), not_flagged as (select s.* from with_latest s where exists (select 1 from orders x where x.customer_id = s.id and x.discount > 0.21)), latest_match as (select s.*, x.account_type from not_flagged s join lateral (select c.account_type from accounts c where c.customer_id = s.id order by c.opened_date desc, c.id desc limit 1) x on true) select id, session_device, account_type from latest_match order by session_device desc
